package com.orcamobile.app.settings;
import org.json.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;

/** Exercises real repository transactions; cloud I/O is deliberately absent. */
public final class CloudPresetRepositoryTest {
    private static int checks;
    private static void check(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
    private interface Work{void run()throws Exception;}
    private static void rejects(Work w,String m)throws Exception{try{w.run();throw new AssertionError(m);}catch(IOException expected){checks++;}}
    private static final class Source implements PresetRepository.SystemSource {
        public List<PresetRepository.SystemRecord> entries(){return Collections.singletonList(new PresetRepository.SystemRecord("process","Vendor","Fine","fine.json","",true));}
        public JSONObject read(String path)throws IOException{try{return new JSONObject("{\"type\":\"process\",\"name\":\"Fine\",\"layer_height\":\"0.2\"}");}catch(JSONException e){throw new IOException(e);}}
        public void close(){}
    }
    private static JSONObject content(String name,String parent,String height)throws Exception{return new JSONObject().put("type","process").put("name",name).put("from","user").put("instantiation","true").put("inherits",parent).put("layer_height",height).put("unknown",new JSONArray("[null,true,{\"nested\":\"preserved\"}]"));}
    private static JSONObject remote(String id,JSONObject c,long time)throws Exception{return new JSONObject().put("id",id).put("content",c).put("updated_time",time);}
    public static void main(String[] args)throws Exception{
        File root=new File(args[0]);root.mkdirs();String account="account-A",other="account-B";
        File inFlight=new File(root,"first-upload-delete");String uploadedId,uploadedCloud;JSONObject sent;
        try(PresetRepository repo=new PresetRepository(inFlight,new Source())){String system=PresetRepository.systemId("process","Vendor","Fine");PresetRepository.Preset p=repo.saveAs(repo.beginDraft(system),"Deleted during first POST");uploadedId=p.id;sent=repo.cloudPending(account).getJSONObject(0);uploadedCloud=sent.getString("id");repo.deleteUser(uploadedId);check(repo.cloudDeletes(account).length()==0,"Never-uploaded deletion initially needs no remote action");rejects(()->repo.cloudPushed(account,uploadedId,sent.getString("source_hash"),44),"Accepted first POST after local deletion must not recreate local profile");check(repo.cloudDeletes(account).length()==1,"Accepted in-flight POST creates a durable tombstone before reporting failure");}
        try(PresetRepository repo=new PresetRepository(inFlight,new Source())){check(repo.cloudDeletes(account).getJSONObject(0).getString("id").equals(uploadedCloud),"First-upload deletion queue survives repository restart");repo.mergeCloud(account,new JSONArray().put(remote(uploadedCloud,sent.getJSONObject("content"),44)));rejects(()->repo.load(uploadedId),"The later server pull cannot resurrect the locally deleted first upload");repo.cloudDeleted(account,uploadedCloud);check(repo.cloudDeletes(account).length()==0,"Confirmed server cleanup consumes the durable reservation");}
        File ambiguous=new File(root,"ambiguous-first-post");String ambiguousId,ambiguousCloud;JSONObject ambiguousSent;
        try(PresetRepository repo=new PresetRepository(ambiguous,new Source())){String system=PresetRepository.systemId("process","Vendor","Fine");PresetRepository.Preset p=repo.saveAs(repo.beginDraft(system),"Ambiguous first POST");ambiguousId=p.id;ambiguousSent=repo.cloudPending(account).getJSONObject(0);ambiguousCloud=ambiguousSent.getString("id");repo.reserveCloudUpload(account,p.id,ambiguousSent.getString("source_hash"));check(repo.mergeCloud(account,new JSONArray())==0&&repo.load(p.id)!=null,"Unacknowledged reservation is not mistaken for a remote deletion");repo.deleteUser(p.id);check(repo.cloudDeletes(account).length()==1,"Deletion during a first POST has a tombstone even without a response");}
        try(PresetRepository repo=new PresetRepository(ambiguous,new Source())){repo.mergeCloud(account,new JSONArray().put(remote(ambiguousCloud,ambiguousSent.getJSONObject("content"),46)));rejects(()->repo.load(ambiguousId),"A server-accepted timed-out POST cannot resurrect its deleted local source after restart");}
        try(PresetRepository repo=new PresetRepository(new File(root,"repo"),new Source())){
            String system=PresetRepository.systemId("process","Vendor","Fine");PresetRepository.Draft draft=repo.beginDraft(system);draft.set("layer_height","0.24");PresetRepository.Preset local=repo.saveAs(draft,"Local");
            JSONArray pending=repo.cloudPending(account);check(pending.length()==1,"New user profile is a pending upload");JSONObject upload=pending.getJSONObject(0);String cloudId=local.id.substring(5);check(upload.getString("id").equals(cloudId),"Stable UUID maps without changing source identity");check(!upload.getJSONObject("content").has("cloud_sync"),"Private mapping is not a ConfigOption");check(upload.optLong("updated_time")==0,"New upload has no server baseline");
            repo.cloudPushed(account,local.id,upload.getString("source_hash"),100);check(repo.cloudPending(account).length()==0,"Successful push marks only sent source clean");check(repo.cloudPending(other).length()==0,"Mapped profile is not uploaded into a different account");check(!repo.exportPreset(local.id).has("cloud_sync"),"Export does not reveal cloud bookkeeping");
            PresetRepository.Preset descendant=repo.saveAs(repo.beginDraft(local.id),"Account child");rejects(()->repo.cloudPending(other),"A pending child cannot upload while its user ancestor belongs to another account");repo.deleteUser(descendant.id);
            PresetRepository.Draft edit=repo.beginDraft(local.id);edit.set("layer_height","0.25");repo.save(edit);JSONObject changed=repo.cloudPending(account).getJSONObject(0);check(changed.optLong("updated_time")==100,"Dirty upload carries exact original server revision");PresetRepository.Draft concurrent=repo.beginDraft(local.id);concurrent.set("layer_height","0.26");repo.save(concurrent);repo.cloudPushed(account,local.id,changed.getString("source_hash"),101);check(repo.cloudPending(account).length()==1,"Edit during upload remains dirty");
            JSONArray sameVersion=new JSONArray().put(remote(cloudId,changed.getJSONObject("content"),101));check(repo.mergeCloud(account,sameVersion)==0,"Unchanged remote baseline does not overwrite dirty local data");check(repo.load(local.id).source.getString("layer_height").equals("0.26"),"Dirty source remains intact");
            JSONArray conflict=new JSONArray().put(remote(cloudId,content("Local","Fine","0.30"),102));rejects(()->repo.mergeCloud(account,conflict),"Changed server and changed local source must conflict");check(repo.load(local.id).source.getString("layer_height").equals("0.26"),"Conflicting merge does not mutate local source");rejects(()->repo.mergeCloud(account,new JSONArray()),"Remote deletion must not discard dirty local edits");
            JSONObject reviewed=repo.cloudReviews(account,conflict).getJSONObject(0);check(reviewed.getJSONObject("local_source").getString("layer_height").equals("0.26")&&reviewed.getJSONObject("server_source").getString("layer_height").equals("0.30"),"Conflict preview contains both actual source versions");PresetRepository.Draft afterReview=repo.beginDraft(local.id);afterReview.set("layer_height","0.27");repo.save(afterReview);rejects(()->repo.acceptCloudReview(account,reviewed,null),"A stale conflict review cannot overwrite newer local edits");check(repo.load(local.id).source.getString("layer_height").equals("0.27"),"Stale review rejection leaves current source intact");JSONObject currentReview=repo.cloudReviews(account,conflict).getJSONObject(0);String duplicate=repo.acceptCloudReview(account,currentReview,"Preserved local version");check(!duplicate.isEmpty()&&repo.load(duplicate).source.getString("layer_height").equals("0.27"),"Duplicate choice preserves local effective values in an independent new profile");check(repo.load(duplicate).parentId.equals(system),"Preserved duplicate uses the stable system ancestor, not the overwritten profile");check(repo.load(local.id).source.getString("layer_height").equals("0.30"),"Duplicate choice applies only the reviewed server version to the original profile");check(!repo.load(duplicate).source.has("setting_id"),"Preserved new copy does not inherit an own cloud setting identity");repo.deleteUser(duplicate);PresetRepository.Draft again=repo.beginDraft(local.id);again.set("layer_height","0.28");repo.save(again);
            JSONObject latest=repo.cloudPending(account).getJSONObject(0);repo.cloudPushed(account,local.id,latest.getString("source_hash"),103);check(repo.mergeCloud(account,new JSONArray().put(remote(cloudId,content("Local","Fine","0.31"),104)))==1,"Clean local source accepts server update");check(repo.load(local.id).source.getString("layer_height").equals("0.31"),"Remote option reaches the actual slicer repository");check(repo.load(local.id).source.getJSONArray("unknown").isNull(0),"Remote unknown structured JSON retains null/type");check(repo.cloudPending(account).length()==0,"Pulled remote source establishes a clean baseline");
            check(repo.mergeCloud(account,new JSONArray().put(remote(cloudId,content("Local","Fine","0.05"),102)))==0,"Older remote source after a newer push/pull cannot roll repository revision backward");check(repo.load(local.id).source.getString("layer_height").equals("0.31")&&repo.cloudPending(account).length()==0,"Ignoring an older remote preserves current values and clean baseline");rejects(()->repo.cloudPushed(account,local.id,latest.getString("source_hash"),103),"An older upload acknowledgment cannot roll back a newer repository revision");
            String parentId="11111111-1111-4111-8111-111111111111",childId="22222222-2222-4222-8222-222222222222";
            JSONArray family=new JSONArray().put(remote(cloudId,content("Local","Fine","0.31"),104)).put(remote(childId.toUpperCase(Locale.ROOT),content("Cloud child","Cloud parent","0.15"),201)).put(remote(parentId,content("Cloud parent","Fine","0.16"),200));check(repo.mergeCloud(account,family)==2,"Out-of-order parent/child batch merges as one transaction");check(repo.load("user:"+childId).parentId.equals("user:"+parentId),"Cloud child links the correct native repository parent");check(repo.systemAncestor("user:"+childId).id.equals(system),"Cloud inheritance still resolves trusted system ancestor");
            int before=repo.list("process").size();JSONArray broken=new JSONArray(family.toString()).put(remote("33333333-3333-4333-8333-333333333333",content("Broken","Missing parent","0.2"),202));rejects(()->repo.mergeCloud(account,broken),"Missing parent rolls back whole cloud batch");check(repo.list("process").size()==before,"Failed cloud batch writes no partial profile");
            PresetRepository.Preset unrelated=repo.saveAs(repo.beginDraft(system),"Unrelated local");JSONArray collision=new JSONArray(family.toString()).put(remote("44444444-4444-4444-8444-444444444444",content("Unrelated local","Fine","0.4"),203));rejects(()->repo.mergeCloud(account,collision),"Cloud name cannot overwrite unassociated local profile");check(repo.load(unrelated.id).source.getString("name").equals("Unrelated local"),"Name-conflicting local source survives");
            repo.deleteUser("user:"+childId);check(repo.cloudDeletes(account).length()==1,"Deleting an associated user schedules exact remote tombstone");check(repo.cloudDeletes(other).length()==0,"Deletion queue is account scoped");repo.save(repo.beginDraft(local.id));check(repo.cloudDeletes(account).length()==1,"Ordinary save retains pending cloud deletions");repo.mergeCloud(account,family);rejects(()->repo.load("user:"+childId),"Pending deletion prevents stale mirror re-import");repo.cloudDeleted(account,childId);check(repo.cloudDeletes(account).length()==0,"Acknowledged remote delete clears only its tombstone");
            JSONArray noChild=new JSONArray().put(remote(cloudId,content("Local","Fine","0.31"),104));check(repo.mergeCloud(account,noChild)==1,"Clean server deletion removes synchronized parent");check(repo.load(unrelated.id)!=null,"Server deletion cannot remove unassociated local source");repo.clearCloudAssociations();check(repo.cloudPending(other).length()==2,"Explicit local sync reset retains profiles and removes account bindings");check(repo.cloudDeletes(account).length()==0,"Explicit local reset does not queue remote deletions");
            rejects(()->repo.mergeCloud(account,null),"Missing snapshot fails closed");rejects(()->repo.cloudPushed(account,local.id,"x",0),"Invalid server timestamp cannot mark clean");
        }
        try(PresetRepository repo=new PresetRepository(new File(root,"review-choices"),new Source())){String system=PresetRepository.systemId("process","Vendor","Fine");PresetRepository.Preset local=repo.saveAs(repo.beginDraft(system),"Reviewed"),unrelated=repo.saveAs(repo.beginDraft(system),"Untouched");JSONObject upload=repo.cloudPending(account).getJSONObject(0);if(!upload.getString("local_id").equals(local.id)){for(int n=0;n<repo.cloudPending(account).length();n++){JSONObject candidate=repo.cloudPending(account).getJSONObject(n);if(candidate.getString("local_id").equals(local.id)){upload=candidate;break;}}}repo.cloudPushed(account,local.id,upload.getString("source_hash"),10);PresetRepository.Draft edit=repo.beginDraft(local.id);edit.set("layer_height","0.25");repo.save(edit);JSONArray snapshot=new JSONArray().put(remote(local.id.substring(5),content("Reviewed","Fine","0.30"),11));JSONObject review=repo.cloudReviews(account,snapshot).getJSONObject(0);int count=repo.list("process").size();rejects(()->repo.acceptCloudReview(account,review,"Untouched"),"Invalid duplicate name cannot partially apply server choice");check(repo.list("process").size()==count&&repo.load(local.id).source.getString("layer_height").equals("0.25"),"Failed duplicate leaves original and all unrelated profiles unchanged");rejects(()->repo.confirmCloudReview(other,local.id,review.getString("local_hash")),"Conflict confirmation rejects another account");repo.acceptCloudReview(account,review,null);check(repo.load(local.id).source.getString("layer_height").equals("0.30"),"Explicit keep-remote changes only the reviewed source");check(repo.load(unrelated.id).source.getString("layer_height").equals("0.2"),"Keep-remote preserves unrelated unsynchronized profile");PresetRepository.Draft dirty=repo.beginDraft(local.id);dirty.set("layer_height","0.33");repo.save(dirty);JSONObject deletedReview=repo.cloudReviews(account,new JSONArray()).getJSONObject(0);check(deletedReview.optBoolean("deleted"),"Review identifies actual server deletion");repo.acceptCloudReview(account,deletedReview,null);rejects(()->repo.load(local.id),"Explicit reviewed remote deletion removes that local profile");check(repo.cloudDeletes(account).length()==0&&repo.load(unrelated.id)!=null,"Accepting an existing server deletion queues no new remote deletion and leaves unrelated source");}
        try(PresetRepository repo=new PresetRepository(new File(root,"stale-reviewed-revision"),new Source())){String system=PresetRepository.systemId("process","Vendor","Fine");PresetRepository.Preset p=repo.saveAs(repo.beginDraft(system),"Revision review");JSONObject initial=repo.cloudPending(account).getJSONObject(0);repo.cloudPushed(account,p.id,initial.getString("source_hash"),10);PresetRepository.Draft dirty=repo.beginDraft(p.id);dirty.set("layer_height","0.25");repo.save(dirty);JSONObject review=repo.cloudReviews(account,new JSONArray().put(remote(p.id.substring(5),content("Revision review","Fine","0.3"),11))).getJSONObject(0);repo.cloudPushed(account,p.id,review.getString("local_hash"),12);rejects(()->repo.acceptCloudReview(account,review,null),"A newer cloud acknowledgment invalidates an older review even when local source bytes did not change");check(repo.load(p.id).source.getString("layer_height").equals("0.25"),"Rejected stale review leaves the newer acknowledged source intact");}
        System.out.println("Cloud preset repository: "+checks+" checks passed; no cloud requests");
    }
}
